const input = $input.first().json;
if (input.query && input.query['hub.mode'] === 'subscribe') {
  return [{ json: { verification: true, challenge: input.query['hub.challenge'] } }];
}
const body = input.body || input;
if (!body?.entry?.[0]?.changes?.[0]?.value?.messages?.[0]) {
  return [{ json: { skip: true, reason: 'Not a message event' } }];
}
const change = body.entry[0].changes[0].value;
const message = change.messages[0];
const contact = change.contacts?.[0];
return [{ json: {
  verification: false, skip: false,
  phone_number: message.from,
  phone_number_id: change.metadata.phone_number_id,
  message_id: message.id, timestamp: message.timestamp,
  contact_name: contact?.profile?.name || 'Unknown',
  message_type: message.type,
  text_body: message.text?.body || '',
  button_reply_id: message.interactive?.button_reply?.id || '',
  button_reply_title: message.interactive?.button_reply?.title || '',
  list_reply_id: message.interactive?.list_reply?.id || '',
  list_reply_title: message.interactive?.list_reply?.title || '',
  action_id: message.interactive?.button_reply?.id || message.interactive?.list_reply?.id || 'NEW_MESSAGE'
}}];

const student = $input.first().json;
const message = $('Parse WhatsApp Message').first().json;
const fullName = student.full_name || student.fields?.full_name || 'Student';

let property_val = student.property || student.fields?.property;
if (Array.isArray(property_val)) property_val = property_val[0];

return [{ json: {
