const student = $('Prepare Student Data').first()?.json || {};
const lease = $('Get Lease Data').first()?.json || {};
const property = $('Get Property Data').first()?.json || {};
const landlord = $('Get Landlord Data').first()?.json || {};

const formatZMW = (amount) => {
  if (!amount) return '0';
  return Number(amount).toLocaleString('en-US');
};

const formatDate = (dateStr) => {
    if (!dateStr) return '';
    const d = new Date(dateStr);
    return d.toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' });
};

const now = new Date();
const months = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];

let leaseDuration = '12';
if (lease.start_date && lease.end_date) {
    const s = new Date(lease.start_date);
    const e = new Date(lease.end_date);
    leaseDuration = Math.round((e - s) / (1000 * 60 * 60 * 24 * 30.44)).toString();
}

return [{
  json: {
    Day: now.getDate().toString(),
    Month: months[now.getMonth()],
    Year: now.getFullYear().toString(),
    landlord_name: landlord.name || landlord.full_name || 'Rukudzo',
    landlord_nrc: 'N/A',
    landlord_phone: landlord.phone_number || 'N/A',
    landlord_email: landlord.email || 'N/A',
    caretaker_name: 'N/A',
    caretaker_phone: 'N/A',
    tenant_name: student.full_name || student.name || '',
    tenant_nrc: student.nationality || student.nrc_number || 'N/A',
    phone_number: student.phone_number || '',
    tenant_email: student.email || 'N/A',
    institution_name: student.school_name || student.institution || 'N/A',
    student_number: student.student_number || 'N/A',
    Programme: (student.faculty || student.programme || '') + (student.year_of_study ? ' - ' + student.year_of_study : ''),
    nok_name: student.next_of_kin_name || 'N/A',
    nok_nrc: student.next_of_kin_nrc || 'N/A',
    "Next of Kin Relationship": student.next_of_kin_relationship || 'N/A',
    nok_phone: student.next_of_kin_phone || 'N/A',
    nok_address: student.next_of_kin_address || 'N/A',
    property_address: property.address || property.property_name || 'N/A',
    plot_number: property.plot_number || 'N/A',
    property_type: property.property_type || 'Student Accommodation',
    lease_start: formatDate(lease.start_date),
    lease_end: formatDate(lease.end_date),
    lease_duration: leaseDuration + ' months',
    monthly_rent: formatZMW(lease.monthly_amount || student.monthly_rent),
    security_deposit: formatZMW(lease.deposit_amount || lease.monthly_amount || student.monthly_rent),
    payment_due_date: lease.payment_due_date || '5th of every month',
    payment_method: student.payment_method_preferred || student.payment_method || 'Bank Transfer / Mobile Money',
    payment_details: 'Refer to Property Manager',
    emergency_contact: landlord.phone_number || 'N/A',
    notice_period: lease.notice_period || '1',
    Responsibility: 'Tenant',
    "Utility Detail": 'Prepaid',
    City: 'Lusaka',
    early_termination_fee: '1 month rent'
  }
}];

