// Unified log - handles Student, Landlord, Unknown
const message = $('Parse WhatsApp Message').first().json;
let userData = {};
try { userData = $('Prepare Student Data').first().json; } catch(e) {
  try { userData = $('Prepare Landlord Data').first().json; } catch(e2) {
    try { userData = $('Prepare Unknown').first().json; } catch(e3) {
      userData = { phone_number: message.phone_number, user_type: 'Unknown', action_id: 'UNKNOWN' };
    }
  }
}
const action = userData.action_id || 'UNKNOWN';
let messageType = 'Text';
let messageContent = message.text_body || '';
let buttonClicked = '';
if (message.message_type === 'interactive') {
  messageType = 'Interactive';
  buttonClicked = message.button_reply_title || message.list_reply_title || action;
  messageContent = 'Action: ' + action;
}
return [{ json: {
  phone_number: userData.phone_number || message.phone_number,
  user_type: userData.user_type || 'Unknown',
  message_direction: 'Inbound',
  message_type: messageType,
  message_content: messageContent,
  button_clicked: buttonClicked
}}];

