const student = $('Prepare Student Data').first().json;
const invoiceStr = $('Get Invoice Data').first().json;
const f = invoiceStr.fields || invoiceStr || {};
const propertyStr = $('Get Property Data (Invoice)').first().json || {};
const property = propertyStr.fields || propertyStr || {};
const landlordStr = $('Get Landlord Data (Invoice)').first().json || {};
const landlord = landlordStr.fields || landlordStr || {};

const now = new Date();
return [{ json: {
  invoice_number: f.invoice_number || 'INV-' + (invoiceStr.id || 'N/A'),
  student_name: student.full_name, room_number: student.room_number,
  phone: student.phone_number, email: student.email,
  property_name: property.property_name || student.property || 'N/A',
  address: property.address || 'N/A',
  landlord_name: landlord.name || 'N/A', landlord_phone: landlord.phone_number || 'N/A',
  month_year: f.month_year || now.toLocaleString('en', {month:'short',year:'numeric'}).toUpperCase(),
  monthly_rent: student.monthly_rent || '2000',
  amount_due: f.amount_due || student.monthly_rent || '2000',
  amount_paid: f.amount_paid || '0',
  balance: (f.amount_due||2000) - (f.amount_paid||0),
  status: f.status || 'Pending',
  status_class: (f.status||'Pending').toLowerCase(),
  issue_date: now.toLocaleDateString('en-GB'),
  due_date: f.due_date || '5th of month',
  airtel_number: 'N/A', bank_name: 'N/A', bank_account: 'N/A',
  generated_date: now.toLocaleDateString('en-GB'),
  phone_number: student.phone_number,
  phone_number_id: student.phone_number_id
}}];

