parameters.jsCode:
const landlord = $('Prepare Landlord Data').first().json;
const properties = $('Get Properties Data').all();
const students = $('Get Students Data').all();
const now = new Date();
const currentMonth = now.toLocaleString('en-US', { month: 'short' }).toUpperCase() + '-' + now.getFullYear();

let msg = '📊 *ZedProp Dashboard*\n';
msg += '━━━━━━━━━━━━━━━━━━━\n';
msg += 'Hello ' + landlord.first_name + ', here is your portfolio overview.\n\n';

// ── PROPERTIES SECTION ──
msg += '🏠 *PROPERTIES*\n';
for (const prop of properties) {
  const f = prop.json.fields || prop.json;
  const name = f.property_name || 'Unknown';
  const address = f.address || '';
  const rooms = f.num_rooms || '—';
  const status = f.status || 'Active';
  const statusIcon = status === 'Active' ? '🟢' : '🔴';
  msg += statusIcon + ' *' + name + '*\n';
  if (address) msg += '   📍 ' + address + '\n';
  msg += '   🛏️ ' + rooms + ' rooms\n';
}
msg += '\n';

// ── STUDENTS ROSTER ──
msg += '👥 *TENANTS (' + students.length + ')*\n';
let paidCount = 0;
let unpaidCount = 0;
let totalRent = 0;

for (const s of students) {
  const sf = s.json.fields || s.json;
  const name = sf.full_name || 'Unknown';
  const room = sf.room_number || '—';
  const rent = parseFloat(sf.monthly_rent) || 0;
  const payStatus = (sf.payment_status_current || sf.payment_status || '').toLowerCase();
  const isPaid = payStatus === 'paid';
  totalRent += rent;
  if (isPaid) { paidCount++; } else { unpaidCount++; }
  const icon = isPaid ? '✅' : '⏳';
  msg += icon + ' ' + name + ' — Rm ' + room + ' — ZMW ' + rent.toLocaleString() + '\n';
}
msg += '\n';

// ── FINANCIAL SUMMARY ──
msg += '💰 *FINANCIAL SUMMARY (' + currentMonth + ')*\n';
msg += '━━━━━━━━━━━━━━━━━━━\n';
msg += '💵 Expected Revenue: *ZMW ' + totalRent.toLocaleString() + '*\n';
const collected = paidCount * (students.length > 0 ? totalRent / students.length : 0);
msg += '✅ Collected: ZMW ' + collected.toLocaleString() + ' (' + paidCount + '/' + students.length + ' tenants)\n';
const outstanding = totalRent - collected;
if (outstanding > 0) {
  msg += '⚠️ Outstanding: *ZMW ' + outstanding.toLocaleString() + '* (' + unpaidCount + ' tenants)\n';
} else {
  msg += '🎉 All tenants up to date!\n';
}
const collectionRate = students.length > 0 ? Math.round((paidCount / students.length) * 100) : 0;
msg += '📈 Collection Rate: ' + collectionRate + '%\n';

return [{ json: {
  dashboard_message: msg,
  phone_number: landlord.phone_number
}}];

const landlord = $('Prepare Landlord Data').first().json;
const invoices = $('Get Invoices Data').all();

let msg = '💰 *Outstanding Balances*\n';
msg += '━━━━━━━━━━━━━━━━━━━\n\n';

if (!invoices || invoices.length === 0 || !invoices[0].json.id) {
  msg += '🎉 All tenants are up to date!\nNo outstanding balances found.\n\n✅ Collection: 100%';
  return [{ json: { outstandings_message: msg, phone_number: landlord.phone_number } }];
}

let totalOutstanding = 0;
let totalDue = 0;
let totalPaid = 0;
let count = 0;
let overdueCount = 0;
let overdueAmount = 0;
let details = [];

for (const inv of invoices) {
  const f = inv.json.fields || inv.json;
  if (!f.amount_due && f.amount_due !== 0) continue;

  const studentName = (Array.isArray(f.student_name) ? f.student_name[0] : f.student_name) || (Array.isArray(f.student) ? f.student[0] : f.student) || 'Unknown';
  const monthYear = f.month_year || 'N/A';
  const amountDue = parseFloat(f.amount_due) || 0;
  const amountPaid = parseFloat(f.amount_paid) || 0;
  const balance = parseFloat(f.balance) || (amountDue - amountPaid);
  const status = f.status || 'Pending';
  const dueDate = f.due_date || '';

  if (balance > 0) {
    count++;
    totalOutstanding += balance;
    totalDue += amountDue;
    totalPaid += amountPaid;
    const isOverdue = status.toLowerCase() === 'overdue';
    if (isOverdue) { overdueCount++; overdueAmount += balance; }
    const statusIcon = isOverdue ? '🔴' : '🟡';
    details.push(statusIcon + ' *' + studentName + '* — ' + monthYear + '\n   Due: ZMW ' + amountDue.toLocaleString() + ' | Paid: ZMW ' + amountPaid.toLocaleString() + '\n   ➡️ Balance: *ZMW ' + balance.toLocaleString() + '* ' + (isOverdue ? '(OVERDUE' + (dueDate ? ' since ' + dueDate : '') + ')' : '(' + status + ')'));
  }
}

if (count === 0) {
  msg += '🎉 All tenants are up to date!\nNo outstanding balances found.\n\n✅ Collection: 100%';
} else {
  // Aging summary first
  if (overdueCount > 0) {
    msg += '🔴 *OVERDUE:* ' + overdueCount + ' invoice(s) — ZMW ' + overdueAmount.toLocaleString() + '\n';
  }
  const currentCount = count - overdueCount;
  const currentAmount = totalOutstanding - overdueAmount;
  if (currentCount > 0) {
    msg += '🟡 *PENDING:* ' + currentCount + ' invoice(s) — ZMW ' + currentAmount.toLocaleString() + '\n';
  }
  msg += '\n';

  // Per-student details
  msg += details.join('\n\n') + '\n\n';

  // Totals
  msg += '━━━━━━━━━━━━━━━━━━━\n';
  msg += '💵 *Total Outstanding: ZMW ' + totalOutstanding.toLocaleString() + '*\n';
  msg += '📊 Tenants with balance: ' + count + '\n';
}

return [{ json: {
  outstandings_message: msg,
  phone_number: landlord.phone_number
}}];

